// runs on every node at startup
async function becomeLeaderAndRun(db, doLeaderWork) {
  const { rows } = await db.query('SELECT pg_try_advisory_lock(7) AS got');
  if (!rows[0].got) return; // someone else is leader
  while (true) {
    await doLeaderWork();      // do the leader's job, forever
    await sleep(1000);
  }
  await db.query('SELECT pg_advisory_unlock(7)');
}
